# 8-bit ALU with flags + tiny BASIC runner (public-domain concept)

def alu_add(a, b, carry_in=0):
    raw = a + b + carry_in
    result = raw & 0xFF
    return {"result": result,
            "carry": (raw >> 8) & 1,
            "zero": 1 if result == 0 else 0,
            "overflow": 1 if ((a ^ result) & (b ^ result) & 0x80) else 0}

# add 200 + 100 the 8-bit way
r = alu_add(200, 100)
print(f"200 + 100 -> {r['result']}  carry={r['carry']} zero={r['zero']} overflow={r['overflow']}")

# Tiny BASIC: 10 PRINT, 20 FOR/NEXT loop like the manuals taught
import re
def tiny_basic(lines):
    prog = {}
    for ln in lines:
        m = re.match(r"(\d+)\s+(.*)", ln)
        prog[int(m.group(1))] = m.group(2)
    keys = sorted(prog)
    pc, i = 0, 0
    stack = []
    while pc < len(keys):
        stmt = prog[keys[pc]]
        if stmt.startswith("PRINT"):
            print(stmt[6:].strip().strip('"'))
        elif stmt.startswith("FOR"):
            var, rest = stmt[4:].split("=")
            lo, hi = map(int, rest.split("TO"))
            stack.append((var.strip(), lo, hi, pc))
        elif stmt.startswith("NEXT"):
            var, lo, hi, at = stack[-1]
            lo += 1
            if lo <= hi:
                stack[-1] = (var, lo, hi, at)
                pc = at
            else:
                stack.pop()
        pc += 1

tiny_basic(['10 PRINT "HELLO 1982"',
            '20 FOR I = 1 TO 3',
            '30 PRINT "READY."',
            '40 NEXT I'])
